<script lang="ts">let { type, targetId, returnTo }: { type: 'link' | 'list'; targetId: string; returnTo: string } = $props(); let open = $state(false);</script>
<button class="link-button" type="button" onclick={() => open = !open}>Report</button>{#if open}<form class="report-form" method="post" action="/report"><input type="hidden" name="type" value={type} /><input type="hidden" name="targetId" value={targetId} /><input type="hidden" name="returnTo" value={returnTo} /><label>Reason <select name="reason"><option value="spam">Spam</option><option value="malware">Malware or unsafe</option><option value="harassment">Harassment</option><option value="illegal">Illegal content</option><option value="misleading">Misleading</option><option value="other">Other</option></select></label><label>Details (optional) <textarea maxlength="1000" name="explanation"></textarea></label><button>Submit report</button></form>{/if}
